window.__S=(function(){
  var G=Arena.Game,W=G.world,CB=Arena.Render.CharacterBackend;
  G._running=false;
  /* La pose es una lista de {mesh, matrix}. La matriz es 4x4 en orden columna:
     [12],[13],[14] es la traslación y la norma de cada columna 3x3 es la escala
     en ese eje. Extraerlo bien importa: la primera versión de esta sonda leía
     campos que no existen y devolvía altura 0 para las seis clases, es decir,
     no medía nada y lo daba por bueno. */
  function norma(m,c){var a=m[c*4],b=m[c*4+1],d=m[c*4+2];return Math.sqrt(a*a+b*b+d*d);}
  window.__firma=function(clase){
    G.setPlayerClass(clase);
    var p=W.getPlayer();
    for(var i=0;i<10;i++){W.stepSeconds(1/60);G.renderer.syncVisuals(1/60);}
    G.renderer.render(1,1/60);
    var v=G.renderer.visuals[p.id], pose=(v&&v.pose)||[];
    var mallas={}, minY=1e9, maxY=-1e9, anchoMax=0, vol=0;
    for(var k=0;k<pose.length;k++){
      var q=pose[k]; if(!q||!q.matrix)continue;
      var m=q.matrix;
      mallas[q.mesh]=(mallas[q.mesh]||0)+1;
      var y=m[13];
      if(y<minY)minY=y; if(y>maxY)maxY=y;
      var sx=norma(m,0), sy=norma(m,1), sz=norma(m,2);
      vol+=sx*sy*sz;
      var ancho=Math.max(sx,sz); if(ancho>anchoMax)anchoMax=ancho;
    }
    var nombres=Object.keys(mallas).sort();
    return {clase:clase, arquetipo:CB.current.archetypeOf(clase), piezas:pose.length,
            mallas:nombres, nMallas:nombres.length,
            altura:+(maxY-minY).toFixed(3), anchoMax:+anchoMax.toFixed(3),
            volumen:+vol.toFixed(4),
            arma:(Arena.Data.weaponOf?Arena.Data.weaponOf(clase):null)};
  };
  return 'listo';
})()

(function(){
  var clases=['devastador','guardian','centinela','rastreador','arcanista','vinculador'];
  var f={},fail=[];
  for(var i=0;i<clases.length;i++) f[clases[i]]=window.__firma(clases[i]);
  // ¿Alguna pareja comparte EXACTAMENTE el mismo conjunto de mallas?
  var iguales=[];
  for(var a=0;a<clases.length;a++)for(var b=a+1;b<clases.length;b++){
    var A=f[clases[a]], B=f[clases[b]];
    /* Umbral RELATIVO. La primera versión pedía |Δvolumen| < 0.02 sobre
       volúmenes de ~45, es decir 0.04 %: no había forma de que fallara y por
       eso decía «ninguno». Dos siluetas se confunden si tienen prácticamente
       las mismas piezas y prácticamente la misma masa. */
    var dVol = Math.abs(A.volumen-B.volumen) / Math.max(A.volumen, B.volumen);
    var dPiezas = Math.abs(A.piezas-B.piezas);
    if(dVol < 0.05 && dPiezas <= 2 && Math.abs(A.altura-B.altura) < 0.08){
      iguales.push(clases[a]+' ≈ '+clases[b]+
        ' (Δmasa '+(dVol*100).toFixed(1)+' %, Δpiezas '+dPiezas+')');
    }
  }
  var arqs={}; for(var c in f) arqs[f[c].arquetipo]=1;
  if(Object.keys(arqs).length<3) fail.push('menos de tres arquetipos visuales');
  for(var d in f){ if(f[d].piezas<20) fail.push(d+' con '+f[d].piezas+' piezas'); }
  /* Se informa, no se falla: el spec §17 sólo exige una familia legible POR
     ARQUETIPO, y eso sí se cumple. Que las seis clases no sean seis identidades
     es una ambición de CLAUDE.md §5 que aún no está, y mentir aquí la escondería. */
  return {assert:!fail.length, fail:fail, paresIndistinguibles:iguales,
          arquetipos:Object.keys(arqs), firmas:f};
})()
